const HindiQuoteArt& getHindiQuoteArt(QuoteCategory category, uint8_t index, FontSize size)
{
    const uint8_t safeCategory = category < QUOTE_CATEGORY_COUNT ? category : QUOTE_CATEGORY_DEFAULT;
    return quotes[safeCategory][index % counts[safeCategory]][size < 3 ? size : FONT_SIZE_MEDIUM];
}

const HindiBitmap& getHindiCategoryArt(QuoteCategory category, FontSize size)
{
    return categories[category < QUOTE_CATEGORY_COUNT ? category : QUOTE_CATEGORY_DEFAULT][size < 3 ? size : FONT_SIZE_MEDIUM];
}

